import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { Medicament } from 'src/app/models/Medicament';
import { FournisseurService } from 'src/app/services/fournisseur.service';

@Component({
  selector: 'app-medicament-list',
  templateUrl: './medicament-list.component.html',
  styleUrls: ['./medicament-list.component.css']
})
export class MedicamentListComponent implements OnInit {
  medicaments: Medicament[] = [];
  fournisseurId: number = 0;

  constructor(
    private fournisseurService: FournisseurService,
    private route: ActivatedRoute
  ) { }

  ngOnInit(): void {
    // Retrieve the fournisseur ID from the route parameters
    this.fournisseurId = +this.route.snapshot.paramMap.get('id')!;
    this.getMedicamentsByFournisseur(this.fournisseurId);
  }

  // Get medicaments of a specific fournisseur
  getMedicamentsByFournisseur(idFournisseur: number): void {
    this.fournisseurService.getMedicamentsByFournisseur(idFournisseur).subscribe(data => {
      this.medicaments = data;
    });
  }
}
<h2>Liste des Médicaments</h2>
<ul>
  <li *ngFor="let medicament of medicaments">
    {{ medicament.nom }} - Prix: {{ medicament.prix }}€
  </li>
</ul>
